-- ============================================================================
-- SOURCE TABLE: GeocodedLocations
-- ============================================================================
-- Static geocoded coordinates for all Project Sleet locations.
-- Generated from Geoapify batch geocoding on 2026-02-18.
--
-- Used as FALLBACK coordinates in Target.Locations (305) when the CPO source
-- data has missing or invalid lat/long. CPO coordinates remain the primary
-- source of truth.
--
-- Source CSV: data/geocoded_by_geoapify-2026-02-18, 17_00_38.csv
-- ============================================================================

SET ROLE db_sleetmigration_owner;

-- Drop and recreate (static data, safe to rebuild)
-- CASCADE: Target.Locations (305) depends on this table and will be recreated later
DROP TABLE IF EXISTS "Source"."GeocodedLocations" CASCADE;

CREATE TABLE "Source"."GeocodedLocations" (
    -- Location GUID (FK to Source.Locations.location_guid / "Id")
    location_guid TEXT PRIMARY KEY,
    
    -- Geocoded coordinates from Geoapify
    latitude DOUBLE PRECISION,
    longitude DOUBLE PRECISION,
    
    -- Geocoding confidence score (0.0 - 1.0)
    confidence DOUBLE PRECISION,
    
    -- Formatted address returned by geocoder
    formatted_address TEXT
);

-- Populate with static geocoded data (179 locations)
